function trier_tableau(arr) {
  // Quick‑sort implementation without using Array.prototype.sort()
  const a = arr.slice();               // work on a copy

  function partition(l, r) {
    let pivot = a[Math.floor((l + r) / 2)];
    while (l < r) {
      if (a[l] > pivot) {
        [a[r], a[l]] = [a[l], a[r]];
        r--;
      } else {
        l++;
      }
    }
    return l;
  }

  function quicksort(l, r) {
    if (l < r) {
      const p = partition(l, r);
      quicksort(l, p - 1);
      quicksort(p + 1, r);
    }
  }

  quicksort(0, a.length - 1);
  return a;
}
