function fusionnerIntervalles(tab) {
  if (!tab.length) return [];

  tab.sort((a, b) => a[0] - b[0]); // sort by start (allowed per spec)

  const merged = [];
  let curStart = tab[0][0];
  let curEnd = tab[0][1];

  for (let i = 1; i < tab.length; i++) {
    if (tab[i][0] <= curEnd) {
      curEnd = Math.max(curEnd, tab[i][1]);
    } else {
      merged.push([curStart, curEnd]);
      curStart = tab[i][0];
      curEnd = tab[i][1];
    }
  }
  merged.push([curStart, curEnd]);
  return merged;
}
```

