function prefixeCommun(tab) {
  if (tab.length === 0) return '';
  const first = tab[0];
  let i = 0;
  while (i < first.length && allStringsMatch(first[i], tab)) i++;
  return first.slice(0, i);
}

function allStringsMatch(prefix, arr) {
  for (const s of arr) if (!s.startsWith(prefix)) return false;
  return true;
}
