function medianeDeuxTries(a, b) {
  const m = a.length + b.length;
  let i = 0, j = 0;

  while (i < a.length && j < b.length) {
    if (a[i] <= b[j]) {
      if ((m % 2 === 1) || (m % 2 === 0 && i > j)) return a[i];
      i++;
    } else {
      if ((m % 2 === 1) || (m % 2 === 0 && j > i)) return b[j];
      j++;
    }
  }

  // one array exhausted
  const remaining = i < a.length ? a.slice(i) : b.slice(j);
  const midIdx = Math.floor(remaining.length / 2);
  return remaining[midIdx];
}
```

