### algo_difficile_1
```javascript
function medianeDeuxTries(a, b) {
  // Ensure a is the shorter array for O(log(min(n,m))) complexity
  if (a.length > b.length) return medianeDeuxTries(b, a);
  const n = a.length, m = b.length;
  let low = 0, high = n;

  while (low <= high) {
    const i = Math.floor((low + high) / 2);          // partition of a
    const j = (n + m + 1) / 2 - i;                    // corresponding partition of b

    const leftMax = Math.max(i > 0 ? a[i - 1] : -Infinity,
                             j > 0 ? b[j - 1] : -Infinity);
    const rightMin = Math.min(i < n ? a[i] : Infinity,
                              j < m ? b[j] : Infinity);

    if (leftMax <= rightMin) {
      // Correct partition found
      return ((n + m) % 2 === 1)
        ? Math.max(leftMax, rightMin)
        : (leftMax + rightMin) / 2;
    } else {
      if (leftMax > rightMin) high = i - 1;
      else low = i + 1;
    }
  }

  // Fallback – should not happen for valid inputs
  return NaN;
}
